import csv
import json
from collections import defaultdict

# ── Read data ──
rows = []
with open('/app/benchmark/data.csv', 'r', encoding='utf-8') as f:
    reader = csv.DictReader(f)
    for row in reader:
        rows.append(row)

# ── Parse composers (split multi-composer entries) ──
def parse_composers(composer_str):
    """Split composer string into individual names, handling commas in multi-composer entries."""
    # The CSV uses commas to separate composers. We need to split carefully.
    # Names like "Richard M. Sherman, Robert B. Sherman" have commas.
    # We split on ", " but need to be careful about special cases.
    parts = [c.strip() for c in composer_str.split(',')]
    # Some names might be split incorrectly (e.g., "W. Franke Harling" is one name)
    # Let's use a smarter approach: split on ", " and check if parts look like names
    composers = []
    current = ""
    for part in composer_str.split(', '):
        if current:
            current += ", " + part
        else:
            current = part
        # A name is complete if it starts with an uppercase and looks like a full name
        # Simple heuristic: if the next part starts with uppercase and current has 2+ words
        # Actually, the simplest approach: each comma-separated part after trimming is a composer
        composers.append(part.strip())
    # Actually let's just split on ", " - that's how the data is formatted
    return [c.strip() for c in composer_str.split(', ')]

# Build structured data
data = []
for row in rows:
    year = int(row['Year'])
    film = row['Film']
    composer_str = row['Composer']
    composers = parse_composers(composer_str)
    data.append({
        'year': year,
        'film': film,
        'composer_str': composer_str,
        'composers': composers,
        'decade': (year // 10) * 10
    })

# ── KPI Calculations ──

# 1. Total Unique Composers
all_composers = set()
for d in data:
    all_composers.update(d['composers'])
total_unique_composers = len(all_composers)

# 2. Maximum Wins by a Single Composer
composer_wins = defaultdict(list)
for d in data:
    for c in d['composers']:
        composer_wins[c].append(d['year'])
max_wins = max(len(v) for v in composer_wins.values())
max_win_composer = [c for c, v in composer_wins.items() if len(v) == max_wins]

# 3. Repeat Winner Rate
# A ceremony is a "repeat win" if ANY of its composers had already won in a prior year
sorted_data = sorted(data, key=lambda x: x['year'])
prior_winners = set()
repeat_ceremonies = 0
for d in sorted_data:
    is_repeat = any(c in prior_winners for c in d['composers'])
    if is_repeat:
        repeat_ceremonies += 1
    prior_winners.update(d['composers'])
repeat_winner_rate = repeat_ceremonies / len(data) * 100

# 4. Decade with Most Unique Winners
decade_composers = defaultdict(set)
for d in data:
    decade_composers[d['decade']].update(d['composers'])
decade_unique_counts = {dec: len(comps) for dec, comps in decade_composers.items()}
max_unique_decade = max(decade_unique_counts, key=decade_unique_counts.get)
max_unique_decade_count = decade_unique_counts[max_unique_decade]

# ── Top Composers Ranking ──
top_composers = sorted(composer_wins.items(), key=lambda x: (-len(x[1]), x[1][0]))
# Only include composers with 2+ wins for the ranking
repeat_winners_list = [(c, years) for c, years in top_composers if len(years) >= 2]

# ── Decade Breakdown ──
decades_sorted = sorted(decade_composers.keys())
decade_stats = []
for dec in decades_sorted:
    composers_in_dec = decade_composers[dec]
    # Count repeat winners in this decade (composers who won in this decade AND had won before)
    years_in_dec = [d for d in sorted_data if d['decade'] == dec]
    prior_before_dec = set()
    for d in sorted_data:
        if d['year'] < dec:
            prior_before_dec.update(d['composers'])
    repeat_in_dec = sum(1 for d in years_in_dec if any(c in prior_before_dec for c in d['composers']))
    # Also count how many composers in this decade had multiple wins WITHIN the decade
    composer_dec_wins = defaultdict(int)
    for d in years_in_dec:
        for c in d['composers']:
            composer_dec_wins[c] += 1
    intra_dec_repeats = sum(1 for c, cnt in composer_dec_wins.items() if cnt > 1)
    decade_stats.append({
        'decade': dec,
        'label': f"{dec}s",
        'num_ceremonies': len(years_in_dec),
        'unique_composers': len(composers_in_dec),
        'repeat_wins_in_decade': repeat_in_dec,
        'intra_decade_repeats': intra_dec_repeats
    })

# ── Era Analysis ──
eras = [
    ('Golden Age', 1934, 1959),
    ('Silver Age', 1960, 1979),
    ('Modern Era', 1980, 1999),
    ('Contemporary Era', 2000, 2026)
]
era_stats = []
for era_name, start, end in eras:
    era_data = [d for d in sorted_data if start <= d['year'] <= end]
    era_composers = set()
    for d in era_data:
        era_composers.update(d['composers'])
    era_composer_wins = defaultdict(int)
    for d in era_data:
        for c in d['composers']:
            era_composer_wins[c] += 1
    top_era_composers = sorted(era_composer_wins.items(), key=lambda x: -x[1])[:5]
    era_stats.append({
        'name': era_name,
        'start': start,
        'end': end,
        'num_ceremonies': len(era_data),
        'unique_composers': len(era_composers),
        'top_composers': top_era_composers,
        'films': [(d['year'], d['film']) for d in era_data]
    })

# ── Notable Milestones ──
# First-time winners (first year each composer appears)
first_wins = {}
for d in sorted_data:
    for c in d['composers']:
        if c not in first_wins:
            first_wins[c] = d['year']

# Longest gap between wins for a single composer
max_gap = 0
max_gap_info = ""
for comp, years in composer_wins.items():
    if len(years) >= 2:
        sorted_years = sorted(years)
        for i in range(1, len(sorted_years)):
            gap = sorted_years[i] - sorted_years[i-1]
            if gap > max_gap:
                max_gap = gap
                max_gap_info = f"{comp}: {sorted_years[i-1]}–{sorted_years[i]} ({gap} years)"

# ── Data for Charts ──
# Decade wins distribution (for bar chart)
decade_labels = [f"{d}s" for d in decades_sorted]
decade_unique_counts_list = [decade_unique_counts[d] for d in decades_sorted]
decade_ceremonies_list = [len([dd for dd in sorted_data if dd['decade'] == d]) for d in decades_sorted]

# Top composers bar chart data
top_n = 15
top_chart_composers = top_composers[:top_n]
top_chart_labels = [c for c, y in top_chart_composers]
top_chart_wins = [len(y) for c, y in top_chart_composers]

# Repeat winner timeline (cumulative)
cumulative_new = []
cumulative_repeat = []
seen_composers = set()
new_count = 0
repeat_count = 0
for d in sorted_data:
    is_repeat = any(c in seen_composers for c in d['composers'])
    if is_repeat:
        repeat_count += 1
    else:
        new_count += 1
    seen_composers.update(d['composers'])
    cumulative_new.append(new_count)
    cumulative_repeat.append(repeat_count)

years_list = [d['year'] for d in sorted_data]

# Era breakdown for pie/donut chart
era_labels_chart = [e['name'] for e in era_stats]
era_counts_chart = [e['num_ceremonies'] for e in era_stats]

# ── Generate JSON data for embedding in HTML ──
chart_data = {
    'years': years_list,
    'decade_labels': decade_labels,
    'decade_unique': decade_unique_counts_list,
    'decade_ceremonies': decade_ceremonies_list,
    'top_composers_labels': top_chart_labels,
    'top_composers_wins': top_chart_wins,
    'cumulative_new': cumulative_new,
    'cumulative_repeat': cumulative_repeat,
    'era_labels': era_labels_chart,
    'era_counts': era_counts_chart,
}

# ── Build HTML ──
def composer_year_detail(comp, years):
    sorted_y = sorted(years)
    return f"{comp} ({len(years)} win{'s' if len(years) > 1 else ''}: {', '.join(str(y) for y in sorted_y)})"

# Top composers table rows
top_table_rows = ""
for i, (comp, years) in enumerate(top_composers[:20], 1):
    sorted_y = sorted(years)
    films = []
    for y in sorted_y:
        for d in sorted_data:
            if d['year'] == y and comp in d['composers']:
                films.append(d['film'])
                break
    film_str = "; ".join(films)
    top_table_rows += f"""<tr>
        <td class="rank">{i}</td>
        <td class="composer-name">{comp}</td>
        <td class="wins">{len(years)}</td>
        <td class="years">{', '.join(str(y) for y in sorted_y)}</td>
        <td class="films">{film_str}</td>
    </tr>\n"""

# Decade table rows
decade_table_rows = ""
for ds in decade_stats:
    decade_table_rows += f"""<tr>
        <td class="decade-label">{ds['label']}</td>
        <td>{ds['num_ceremonies']}</td>
        <td>{ds['unique_composers']}</td>
        <td>{ds['intra_decade_repeats']}</td>
        <td>{ds['unique_composers']/ds['num_ceremonies']*100:.0f}%</td>
    </tr>\n"""

# Era sections
era_sections = ""
for es in era_stats:
    top_comp_str = ", ".join(f"{c} ({cnt})" for c, cnt in es['top_composers'])
    notable_films = es['films'][:5]  # first 5 films
    films_str = "; ".join(f"<em>{f}</em> ({y})" for y, f in notable_films)
    era_sections += f"""<div class="era-card">
        <h3>{es['name']} <span class="era-range">({es['start']}–{es['end']})</span></h3>
        <div class="era-stats-row">
            <div class="era-stat"><span class="era-stat-num">{es['num_ceremonies']}</span> ceremonies</div>
            <div class="era-stat"><span class="era-stat-num">{es['unique_composers']}</span> unique composers</div>
        </div>
        <p><strong>Defining composers:</strong> {top_comp_str}</p>
        <p><strong>Notable winning films:</strong> {films_str}…</p>
    </div>\n"""

# Milestones
milestones_html = ""
# First winner
first_row = sorted_data[0]
milestones_html += f"""<div class="milestone-card">
    <div class="milestone-icon">🏆</div>
    <div class="milestone-text"><strong>First recorded winner:</strong> {first_row['composer_str']} for <em>{first_row['film']}</em> ({first_row['year']})</div>
</div>\n"""

# Most recent winner
last_row = sorted_data[-1]
milestones_html += f"""<div class="milestone-card">
    <div class="milestone-icon">🎬</div>
    <div class="milestone-text"><strong>Most recent winner:</strong> {last_row['composer_str']} for <em>{last_row['film']}</em> ({last_row['year']})</div>
</div>\n"""

# Longest gap
milestones_html += f"""<div class="milestone-card">
    <div class="milestone-icon">⏳</div>
    <div class="milestone-text"><strong>Longest gap between wins:</strong> {max_gap_info}</div>
</div>\n"""

# Most wins
for c in max_win_composer:
    milestones_html += f"""<div class="milestone-card">
        <div class="milestone-icon">👑</div>
        <div class="milestone-text"><strong>Most wins:</strong> {c} with {max_wins} wins ({', '.join(str(y) for y in sorted(composer_wins[c]))})</div>
    </div>\n"""

# First female composer winner (Hildur Guðnadóttir 2019)
for d in sorted_data:
    if 'Hildur' in d['composer_str']:
        milestones_html += f"""<div class="milestone-card">
            <div class="milestone-icon">🌟</div>
            <div class="milestone-text"><strong>First solo female composer winner:</strong> {d['composer_str']} for <em>{d['film']}</em> ({d['year']})</div>
        </div>\n"""
        break

# Back-to-back wins
back_to_back = []
for comp, years in composer_wins.items():
    sorted_y = sorted(years)
    for i in range(1, len(sorted_y)):
        if sorted_y[i] - sorted_y[i-1] == 1:
            back_to_back.append((comp, sorted_y[i-1], sorted_y[i]))
back_to_back_str = "; ".join(f"{c} ({y1}–{y2})" for c, y1, y2 in back_to_back)
if back_to_back_str:
    milestones_html += f"""<div class="milestone-card">
        <div class="milestone-icon">🔗</div>
        <div class="milestone-text"><strong>Consecutive-year wins:</strong> {back_to_back_str}</div>
    </div>\n"""

# Repeat winner rate detail
repeat_composers = [(c, sorted(years)) for c, years in composer_wins.items() if len(years) >= 2]
repeat_composers_str = ", ".join(f"{c} ({', '.join(str(y) for y in years)})" for c, years in sorted(repeat_composers, key=lambda x: -len(x[1])))

# JSON for charts
chart_json = json.dumps(chart_data)

html = f"""<!DOCTYPE html>
<html lang="en">
<head>
    <meta charset="UTF-8">
    <meta name="viewport" content="width=device-width, initial-scale=1.0">
    <title>Nine Decades of Oscar-Winning Scores</title>
    <script src="https://cdn.jsdelivr.net/npm/chart.js@4.4.7/dist/chart.umd.min.js"></script>
    <style>
        :root {{
            --bg-primary: #0f0f13;
            --bg-secondary: #1a1a24;
            --bg-card: #22222e;
            --bg-card-hover: #2a2a3a;
            --text-primary: #e8e6f0;
            --text-secondary: #a09cb0;
            --text-muted: #6b6780;
            --accent-gold: #d4a843;
            --accent-gold-light: #f0d078;
            --accent-blue: #4a90d9;
            --accent-teal: #3abfb0;
            --accent-rose: #d94a6e;
            --accent-purple: #9b6ed9;
            --border: #2e2e40;
            --shadow: 0 4px 24px rgba(0,0,0,0.3);
        }}

        * {{ margin: 0; padding: 0; box-sizing: border-box; }}

        body {{
            font-family: 'Segoe UI', -apple-system, BlinkMacSystemFont, 'Helvetica Neue', sans-serif;
            background: var(--bg-primary);
            color: var(--text-primary);
            line-height: 1.6;
            -webkit-font-smoothing: antialiased;
        }}

        .container {{
            max-width: 1200px;
            margin: 0 auto;
            padding: 0 32px;
        }}

        /* Hero */
        .hero {{
            padding: 80px 0 60px;
            text-align: center;
            background: linear-gradient(180deg, #1a1525 0%, var(--bg-primary) 100%);
            border-bottom: 1px solid var(--border);
        }}
        .hero-overline {{
            font-size: 0.85rem;
            letter-spacing: 3px;
            text-transform: uppercase;
            color: var(--accent-gold);
            margin-bottom: 16px;
        }}
        .hero h1 {{
            font-size: 3rem;
            font-weight: 700;
            line-height: 1.15;
            color: #fff;
            margin-bottom: 16px;
        }}
        .hero-sub {{
            font-size: 1.15rem;
            color: var(--text-secondary);
            max-width: 700px;
            margin: 0 auto;
        }}

        /* KPI Strip */
        .kpi-strip {{
            display: grid;
            grid-template-columns: repeat(4, 1fr);
            gap: 20px;
            padding: 48px 0;
        }}
        .kpi-card {{
            background: var(--bg-card);
            border: 1px solid var(--border);
            border-radius: 12px;
            padding: 28px 24px;
            text-align: center;
            transition: transform 0.2s, border-color 0.2s;
        }}
        .kpi-card:hover {{
            transform: translateY(-2px);
            border-color: var(--accent-gold);
        }}
        .kpi-value {{
            font-size: 2.8rem;
            font-weight: 800;
            color: var(--accent-gold-light);
            line-height: 1;
            margin-bottom: 8px;
        }}
        .kpi-label {{
            font-size: 0.85rem;
            color: var(--text-secondary);
            text-transform: uppercase;
            letter-spacing: 1px;
        }}

        /* Sections */
        section {{
            padding: 56px 0;
            border-top: 1px solid var(--border);
        }}
        .section-label {{
            font-size: 0.8rem;
            letter-spacing: 2.5px;
            text-transform: uppercase;
            color: var(--accent-gold);
            margin-bottom: 8px;
        }}
        .section-title {{
            font-size: 2rem;
            font-weight: 700;
            color: #fff;
            margin-bottom: 8px;
        }}
        .section-desc {{
            font-size: 1rem;
            color: var(--text-secondary);
            margin-bottom: 32px;
            max-width: 800px;
        }}

        /* Charts */
        .chart-grid {{
            display: grid;
            grid-template-columns: 1fr 1fr;
            gap: 24px;
            margin-bottom: 32px;
        }}
        .chart-card {{
            background: var(--bg-card);
            border: 1px solid var(--border);
            border-radius: 12px;
            padding: 24px;
        }}
        .chart-card.full-width {{
            grid-column: 1 / -1;
        }}
        .chart-title {{
            font-size: 1rem;
            font-weight: 600;
            color: var(--text-primary);
            margin-bottom: 16px;
        }}
        canvas {{
            width: 100% !important;
            max-height: 380px;
        }}

        /* Tables */
        .table-wrap {{
            overflow-x: auto;
            margin-top: 24px;
            border-radius: 10px;
            border: 1px solid var(--border);
        }}
        table {{
            width: 100%;
            border-collapse: collapse;
