    reader = csv.DictReader(f)
    for row in reader:
        rows.append(row)

# ── Parse composers (split multi-composer entries) ──
def parse_composers(composer_str):
    """Split composer string into individual names, handling commas in multi-composer entries."""
    # The CSV uses commas to separate composers. We need to split carefully.
    # Names like "Richard M. Sherman, Robert B. Sherman" have commas.
    # We split on ", " but need to be careful about special cases.
    parts = [c.strip() for c in composer_str.split(',')]
    # Some names might be split incorrectly (e.g., "W. Franke Harling" is one name)
    # Let's use a smarter approach: split on ", " and check if parts look like names
    composers = []
    current = ""
    for part in composer_str.split(', '):
        if current:
            current += ", " + part
        else:
            current = part
        # A name is complete if it starts with an uppercase and looks like a full name
        # Simple heuristic: if the next part starts with uppercase and current has 2+ words
        # Actually, the simplest approach: each comma-separated part after trimming is a composer
        composers.append(part.strip())
    # Actually let's just split on ", " - that's how the data is formatted
    return [c.strip() for c in composer_str.split(', ')]

# Build structured data
data = []
for row in rows:
    year = int(row['Year'])
    film = row['Film']
    composer_str = row['Composer']
    composers = parse_composers(composer_str)
    data.append({
        'year': year,
        'film': film,
        'composer_str': composer_str,
        'composers': composers,
        'decade': (year // 10) * 10
    })

# ── KPI Calculations ──

# 1. Total Unique Composers
all_composers = set()
for d in data:
    all_composers.update(d['composers'])
total_unique_composers = len(all_composers)

# 2. Maximum Wins by a Single Composer
composer_wins = defaultdict(list)
for d in data:
    for c in d['composers']:
        composer_wins[c].append(d['year'])
max_wins = max(len(v) for v in composer_wins.values())
max_win_composer = [c for c, v in composer_wins.items() if len(v) == max_wins]

# 3. Repeat Winner Rate
# A ceremony is a "repeat win" if ANY of its composers had already won in a prior year
sorted_data = sorted(data, key=lambda x: x['year'])
prior_winners = set()
repeat_ceremonies = 0
for d in sorted_data:
    is_repeat = any(c in prior_winners for c in d['composers'])
    if is_repeat:
        repeat_ceremonies += 1
    prior_winners.update(d['composers'])
repeat_winner_rate = repeat_ceremonies / len(data) * 100

# 4. Decade with Most Unique Winners
decade_composers = defaultdict(set)
for d in data:
    decade_composers[d['decade']].update(d['composers'])
decade_unique_counts = {dec: len(comps) for dec, comps in decade_composers.items()}
max_unique_decade = max(decade_unique_counts, key=decade_unique_counts.get)
max_unique_decade_count = decade_unique_counts[max_unique_decade]

# ── Top Composers Ranking ──
top_composers = sorted(composer_wins.items(), key=lambda x: (-len(x[1]), x[1][0]))
# Only include composers with 2+ wins for the ranking
