    # Count repeat winners in this decade (composers who won in this decade AND had won before)
    years_in_dec = [d for d in sorted_data if d['decade'] == dec]
    prior_before_dec = set()
    for d in sorted_data:
        if d['year'] < dec:
            prior_before_dec.update(d['composers'])
    repeat_in_dec = sum(1 for d in years_in_dec if any(c in prior_before_dec for c in d['composers']))
    # Also count how many composers in this decade had multiple wins WITHIN the decade
    composer_dec_wins = defaultdict(int)
    for d in years_in_dec:
        for c in d['composers']:
            composer_dec_wins[c] += 1
    intra_dec_repeats = sum(1 for c, cnt in composer_dec_wins.items() if cnt > 1)
    decade_stats.append({
        'decade': dec,
        'label': f"{dec}s",
        'num_ceremonies': len(years_in_dec),
        'unique_composers': len(composers_in_dec),
