# ── Data for Charts ──
# Decade wins distribution (for bar chart)
decade_labels = [f"{d}s" for d in decades_sorted]
decade_unique_counts_list = [decade_unique_counts[d] for d in decades_sorted]
decade_ceremonies_list = [len([dd for dd in sorted_data if dd['decade'] == d]) for d in decades_sorted]

# Top composers bar chart data
top_n = 15
top_chart_composers = top_composers[:top_n]
top_chart_labels = [c for c, y in top_chart_composers]
top_chart_wins = [len(y) for c, y in top_chart_composers]

# Repeat winner timeline (cumulative)
cumulative_new = []
cumulative_repeat = []
seen_composers = set()
new_count = 0
repeat_count = 0
for d in sorted_data:
    is_repeat = any(c in seen_composers for c in d['composers'])
