            x: {{ grid: {{ display: false }} }}
        }}
    }}
}});

// Decade ceremonies
new Chart(document.getElementById('decadeCeremoniesChart'), {{
    type: 'bar',
    data: {{
        labels: chartData.decade_labels,
        datasets: [{{
            label: 'Ceremonies',
            data: chartData.decade_ceremonies,
            backgroundColor: '#4a90d9',
            borderRadius: 6,
            barPercentage: 0.7
        }}]
    }},
    options: {{
        responsive: true,
        plugins: {{ legend: {{ display: false }} }},
        scales: {{
            y: {{ beginAtZero: true, grid: {{ color: '#1e1e2e' }} }},
            x: {{ grid: {{ display: false }} }}
        }}
    }}
}});

// Top composers
new Chart(document.getElementById('topComposersChart'), {{
    type: 'bar',
    data: {{
        labels: chartData.top_composers_labels,
        datasets: [{{
            label: 'Wins',
            data: chartData.top_composers_wins,
            backgroundColor: chartData.top_composers_wins.map((v, i) => {{
                if (i === 0) return '#d4a843';
                if (v >= 3) return '#f0d078';
