            }}),
            borderRadius: 6,
            barPercentage: 0.65
        }}]
    }},
    options: {{
        indexAxis: 'y',
        responsive: true,
        plugins: {{ legend: {{ display: false }} }},
        scales: {{
            x: {{ beginAtZero: true, grid: {{ color: '#1e1e2e' }}, ticks: {{ stepSize: 1 }} }},
            y: {{ grid: {{ display: false }} }}
        }}
    }}
}});

// Repeat timeline
new Chart(document.getElementById('repeatTimelineChart'), {{
    type: 'line',
    data: {{
        labels: chartData.years,
        datasets: [
            {{
                label: 'Cumulative New Winners',
                data: chartData.cumulative_new,
                borderColor: '#3abfb0',
                backgroundColor: 'rgba(58,191,176,0.1)',
                fill: true,
                tension: 0.3,
                pointRadius: 0
            }},
            {{
                label: 'Cumulative Repeat Wins',
                data: chartData.cumulative_repeat,
                borderColor: '#d94a6e',
                backgroundColor: 'rgba(217,74,110,0.1)',
                fill: true,
                tension: 0.3,
                pointRadius: 0
            }}
        ]
    }},
    options: {{
        responsive: true,
        plugins: {{ legend: {{ position: 'bottom' }} }},
        scales: {{
            y: {{ grid: {{ color: '#1e1e2e' }} }},
            x: {{
                grid: {{ display: false }},
                ticks: {{ maxTicksLimit: 12 }}
            }}
        }}
    }}
}});

// Diversity chart (unique/ceremonies ratio per decade)
const diversityRate = chartData.decade_unique.map((u, i) => (u / chartData.decade_ceremonies[i] * 100).toFixed(1));
new Chart(document.getElementById('diversityChart'), {{
    type: 'line',
    data: {{
        labels: chartData.decade_labels,
        datasets: [{{
            label: 'Diversity Rate (%)',
            data: diversityRate,
            borderColor: '#9b6ed9',
            backgroundColor: 'rgba(155,110,217,0.15)',
            fill: true,
            tension: 0.3,
            pointRadius: 5,
            pointBackgroundColor: '#9b6ed9'
        }}]
    }},
    options: {{
        responsive: true,
        plugins: {{ legend: {{ display: false }} }},
        scales: {{
            y: {{ min: 0, max: 120, grid: {{ color: '#1e1e2e' }}, ticks: {{ callback: v => v + '%' }} }},
            x: {{ grid: {{ display: false }} }}
        }}
    }}
}});

// Era chart
const eraColors = ['#d4a843', '#4a90d9', '#3abfb0', '#9b6ed9'];
new Chart(document.getElementById('eraChart'), {{
    type: 'doughnut',
    data: {{
        labels: chartData.era_labels,
        datasets: [{{
            data: chartData.era_counts,
            backgroundColor: eraColors,
            borderColor: '#1a1a24',
